using System;using System.IO;using System.Reflection;using System.Linq;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class SignatureDrawingValidation{
 static SignatureDrawingValidation(){EditorApplication.delayCall+=Run;}
 static void Run(){string path="D:/-11-scene3-audit/signature-validation.txt";if(File.Exists(path))return;if(EditorApplication.isUpdating||EditorApplication.isCompiling){EditorApplication.delayCall+=Run;return;}GameObject host=null;Texture2D ink=null;FieldInfo field=null;Scene3SignatureForm form=null;try{host=new GameObject("Temporary signature validation"){hideFlags=HideFlags.HideAndDontSave};form=host.AddComponent<Scene3SignatureForm>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;field=typeof(Scene3SignatureForm).GetField("ink",flags);ink=new Texture2D(768,384,TextureFormat.RGBA32,false);field.SetValue(form,ink);typeof(Scene3SignatureForm).GetMethod("ClearInk",flags).Invoke(form,null);typeof(Scene3SignatureForm).GetMethod("Stroke",flags).Invoke(form,new object[]{new Vector2(-5,1),new Vector2(780,380)});int count=ink.GetPixels32().Count(p=>p.a>0);if(count<100||count>10000)throw new Exception("Unexpected stroke coverage: "+count);typeof(Scene3SignatureForm).GetMethod("ClearInk",flags).Invoke(form,null);if(ink.GetPixels32().Any(p=>p.a!=0))throw new Exception("Clear did not erase every pixel");if(!Scene3HumanDialogue.Dialogue.Contains("You can return to sign the form later."))throw new Exception("Dialogue text missing");File.WriteAllText(path,"PASS: signature drawing clips to canvas bounds\nPASS: stroke produces visible ink\nPASS: clear resets transparent canvas\nPASS: complete reception text retained\nUnity script compilation passed\nPlay-mode proximity and full signing flow not automatically exercised");}catch(Exception e){File.WriteAllText(path,"FAIL: "+e);}finally{if(form&&field!=null)field.SetValue(form,null);if(host)UnityEngine.Object.DestroyImmediate(host);if(ink)UnityEngine.Object.DestroyImmediate(ink);}}
}
